/**
 *
 * DataTableSortOrder renders the 1-based priority badge for a sorted column while multi-column
 * sorting is active. Hidden when the column is not part of the active sort set.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableSortOrder
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
export type DataTableSortOrderPassThroughType<E> = PassThroughType<DataTableSortOrderInstance, E>;
export interface DataTableSortOrderPassThrough {
    root?: DataTableSortOrderPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
export interface DataTableSortOrderProps extends BaseComponentProps<DataTableSortOrderInstance, unknown, DataTableSortOrderPassThrough, 'span'> {
}
export interface DataTableSortOrderState {
}
export interface DataTableSortOrderExposes {
    datatable: DataTableRootInstance | undefined | null;
    /**
     * Zero-based position of this column inside the active multi-sort set, or `-1` when the
     * column is not part of the current sort.
     */
    sortIndex: number;
    /**
     * One-based badge number derived from `sortIndex` (e.g. `1`, `2`, `3`). Exposed for
     * convenience in the `children` render prop.
     */
    index: number;
}
export type DataTableSortOrderInstance = ComponentInstance<DataTableSortOrderProps, DataTableSortOrderState, DataTableSortOrderExposes>;
